60	/* step/push/wait are mean milliseconds per frame spent in the hack, in
61	 * pushImage, and waiting out what is left of the hack's requested delay after
62	 * the push (including button polling). */
63	static void printStats(const char *tag) {
64	  float n = frames ? (float)frames : 1.0f;
65	  Serial.printf(
66	      "%s %s fps=%.1f step=%.1fms push=%.1fms wait=%.1fms heap=%u psram=%u\n",
67	      tag, g_hacks[runner_index(runner)]->name,
68	      frames * 1000.0f / kStatsEveryMs, stepUs / n / 1000.0f,
69	      pushUs / n / 1000.0f, waitUs / n / 1000.0f, (unsigned)ESP.getFreeHeap(),
70	      (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
71	}
