73	/* Returns true if a button switched hacks (which also resets the stats). */
74	static bool pollButtons() {
75	  bool switched = false;
76	  uint32_t pressedAt = 0;
77	  if (button_latch_take(&latchA, &pressedAt)) {
78	    runner_next(runner);
79	    switched = true;
80	  }
81	  if (button_latch_take(&latchB, &pressedAt)) {
82	    runner_prev(runner);
83	    switched = true;
84	  }
85	  if (switched) {
86	    Serial.printf("switch -> %s press_waited=%ums heap=%u psram=%u\n",
87	                  g_hacks[runner_index(runner)]->name,
88	                  (unsigned)(millis() - pressedAt),
89	                  (unsigned)ESP.getFreeHeap(),
90	                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
91	    resetStats();
92	  }
93	  return switched;
94	}
