96	void setup() {
97	  auto cfg = M5.config();
98	  M5.begin(cfg);
99	  Serial.begin(115200);
100	  M5.Display.setSwapBytes(false);
101	
102	  button_latch_init(&latchA, kButtonSettleMs);
103	  button_latch_init(&latchB, kButtonSettleMs);
104	  xTaskCreatePinnedToCore(buttonTask, "buttons", 2048, nullptr, 2, nullptr, 0);
105	
106	  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
107	    halt("PSRAM alloc failed");
108	  runner = runner_create(&canvas);
109	  if (!runner || runner_start(runner, 0) != 0) halt("hack start failed");
110	  printStats("boot");
111	  resetStats();
112	}
